        @"إذا لم يظهر التطبيق على الفور بعد التثبيت، فقم بإعادة الاتصال هنا ويجب أن يظهر بعد ذلك.",
        @"يتم تثبيت ldid ويسمح ل ESign بتثبيت ملفات IPA غير الموقعة.",
        @"قم بتثبيت ldid",
        @"قم بتثبيت مساعد ESign",
        @"قم بإلغاء تثبيت ESign",
        @"حدد تطبيق النظام الذي تريد الكتابة فوقه",
        @"حدد تطبيق نظام لتثبيت مساعد ESign فيه. لن تكون الوظيفة العادية للتطبيق متاحة، لذلك يوصى باختيار شيء عديم الفائدة مثل تطبيق النصائح.",
        @"When iOS rebuilds the icon cache, all ESign apps including ESign itself will be reverted to \"User\" state and either disappear or no longer launch. The only way to have persistence in a rootless environment is to replace a system application, here you can select a system app to replace with a esign helper that can be used to refresh the registrations of all ESign related apps in case they disappear or no longer launch.",
        @"لا يوجد إذن بالمشاركة",
        @"غير قادر على مشاركة الملفات باستخدام ESign المثبت بشكل دائم، هل تريد المشاركة عبر تطبيق Jump [File]؟",
        @"مساحة التخزين",
        @"يتم حساب مساحة التخزين. يستغرق الأمر بعض الوقت. من فضلك انتظر بصبر...",
        @"مساحة تخزين الجهاز",
        @"ESign مساحة مستعملة",
        @"There is a problem with the storage space calculation of the phone Settings, sometimes there is a cache. \n ESin files is stored in Documents. If you want to clear the space, you can enter the file list and delete the file. \nLibrary files are automatically generated by the system, with some necessary information stored, do not take up too much space, ignore.",
        @"إجمالي مساحة القرص",
        @"مساحة القرص المستخدمة",
        @"مساحة حرة على القرص",
        @"ملف IPA غير موجود أو لا يمكن الوصول إليه.",
        @"لا يبدو أن ملف IPA يحتوي على تطبيق ",
        @"فشل في إنشاء حاوية لحزمة التطبيقات.",
        @"تم بالفعل تثبيت تطبيق غير متجر ESign بنفس المعرف. إذا كنت متأكدا تماما من أنه ليس كذلك، فيمكنك فرض تثبيته.",
        @"لا يحتوي التطبيق على ملف Info.plist.",
        @"لم يتم توقيع التطبيق بشهادة CoreTrust مزيفة ولم يتم تثبيت ldid. قم بتثبيت ldid في علامة التبويب الإعدادات وحاول مرة أخرى.",
        @"التطبيقات الرئيسية القابلة للتنفيذ غير موجودة.",
        @"فشل في التوقيع على التطبيق. أعاد ldid رمز حالة غير صفري.",
        @"تفتقر التطبيقات Info.plist إلى القيم المطلوبة.",
        @"فشل في وضع علامة على التطبيق كتطبيق ESignStore",
        @"فشل في نسخ حزمة التطبيقات.",
        @"خطأ غير معروف",
        @"استحقاقات التوقيع المخصصة، قد لا يتم تثبيتها بعد التوقيع.",
        @"تعديل التكوين فقط، تجاهل التوقيع",
        @"تعديل التكوين فقط",
        @"استخدام الاستحقاقات المخصصة توقيع الملف",
        @"يحتوي ملف الاستحقاقات على أخطاء.",
        @"يحتوي التطبيق الذي حاولت تثبيته على نفس معرف تطبيق النظام المثبت بالفعل على الجهاز. تم منع التثبيت لحمايتك من التمهيدات المحتملة أو غيرها من المشكلات.",
        @"فشل في التعديل",
        @"Switching this app to a \"User\" registration will make it unlaunchable after the next respring. \nThe purpose of this option is to make the app temporarily show up in settings, so you can adjust the settings and then switch it back to a \"System\" registration. Additionally, the \"User\" registration state is also useful to temporarily fix iTunes file sharing.\nWhen you're done making the changes you need and want the app to become launchable again, you will need to switch it back to \"System\" state.",
        @"Switching to \"User\"",
        @"Switching to \"%@\"",
        @"[%@] تم بنجاح %@ ويوجد ملف باسم '%@' بالفعل في هذا الموقع",
        @"نقل ",
